export { Subflow } from './Subflow'
export * from './FlowTypes'
import { FlowLogic } from './flow-logic'
import { Stage } from './flow-logic/stage'
export { FlowStage } from './flow-logic'
export type { FlowStageConfig, FlowStageStates } from './flow-logic'
export * from './FlowVariables'
export * from './transform'
export * from './built-ins'
import { ActionInstance } from './Action'
export { Action } from './Action'
import { ActionStep } from './ActionStep'
export { ActionStep, ActionStepDefinition } from './ActionStep'
import { SubflowInstance } from './Subflow'
import { AssignActionOutputs } from './assign-action-outputs'
import { ErrorEvaluation } from './error-evaluation'
import {
    InlineScript as InlineScriptFunction,
    dataPill as dataPillAlias,
    ApprovalRules,
    ApprovalDueDate,
} from './flow-data-helpers'

export { ARRAY_FLOW_DATA_TYPES } from './flow-data-helpers'

export type {
    ArrayFlowDataType,
    FlowDataType,
    ApprovalRulesType,
    ApprovalConditionRuleType,
    ApprovalRuleActionType,
    ApprovalRuleConditionType,
    ApprovalRuleSetType,
    ApprovalDueDateType,
} from './flow-data-helpers'

/**
 * The core building blocks for defining Flows and Subflows.
 *
 * ```typescript
 * import { wfa } from '@servicenow/sdk/automation'
 * ```
 * @group Flow
 */
export namespace wfa {
    /** Register the trigger that starts the flow. Pass a trigger definition from the `trigger` built-ins. */
    export const trigger = Trigger

    /** Execute an action instance within a flow. Pass an Action definition. */
    export const action = ActionInstance

    /** Execute a step instance within an action definition. Pass a step definition from the `actionStep` built-ins. */
    export const actionStep = ActionStep

    /** Control flow operators for branching, looping, and flow control (`if`, `elseIf`, `else`, `forEach`,
     * `waitForADuration`, `setFlowVariables`, `appendToFlowVariables`, `assignSubflowOutputs`, `endFlow`, `exitLoop`,
     * `skipIteration`). */
    export const flowLogic = FlowLogic

    /** Activate a flow stage declared in the `stages` config header. Pass `params.stages.<key>`. */
    export const stage = Stage

    /** Create a typed data pill reference to a prior step's output or trigger data. */
    export const dataPill = dataPillAlias

    /** Define a server-side script inline as an action or subflow input. */
    export const inlineScript = InlineScriptFunction

    /** Build a structured approval rules configuration for `action.core.askForApproval`. */
    export const approvalRules = ApprovalRules

    /** Define a due-date policy for an `action.core.askForApproval` step. */
    export const approvalDueDate = ApprovalDueDate

    /** Assign action output values in the body, enabling datapill references to step results. */
    export const assignActionOutputs = AssignActionOutputs

    /** Define error evaluation conditions for an action, evaluated after all steps complete. */
    export const errorEvaluation = ErrorEvaluation

    // Subflow Instance
    export const subflow = SubflowInstance
}
